let token='',D={requests:[],items:[],offers:[],orders:[],orderItems:[],orderDocuments:[],suppliers:[],products:[],units:[],leadTimes:[],requestSuppliers:[],supplierContacts:[],permissions:{}},saveAction=null,itemCounter=0,requestLimit=60,startupProductId=new URLSearchParams(location.search).get('product_id')||'';
if(new URLSearchParams(location.search).get('embedded')==='1')document.body.classList.add('embedded');
function getToken(){try{if(parent&&parent!==window&&parent.__PORTAL_TOKEN__)return parent.__PORTAL_TOKEN__}catch{}try{if(opener&&opener.__PORTAL_TOKEN__)return opener.__PORTAL_TOKEN__}catch{}return sessionStorage.getItem('portal_procurement_token')||''}
function requestToken(){return new Promise(resolve=>{if(!('BroadcastChannel'in window))return resolve('');const channel=new BroadcastChannel('livion-portal-session'),requestId=crypto.randomUUID(),timer=setTimeout(()=>{channel.close();resolve('')},1800);channel.onmessage=e=>{if(e.data?.type==='PORTAL_TOKEN_RESPONSE'&&e.data?.requestId===requestId){clearTimeout(timer);channel.close();resolve(e.data.token||'')}};channel.postMessage({type:'PORTAL_TOKEN_REQUEST',requestId})})}
