async function api(path,opt={}){const send=async t=>{const headers={authorization:'Bearer '+t,...(opt.headers||{})};if(!(opt.body instanceof FormData))headers['content-type']='application/json';return fetch(API+path,{...opt,headers,cache:'no-store'})};token=await renew(false)||token;if(!token){openThroughPortal();throw Error('Abrindo pelo Portal Livion…')}sessionStorage.setItem('portal_procurement_token',token);let response=await send(token);if(response.status===401){token=await renew(true)||token;if(!token){openThroughPortal();throw Error('Abrindo pelo Portal Livion…')}response=await send(token)}const body=await response.json().catch(()=>({}));if(!response.ok)throw Error(translateError(body.error||String(response.status)));return body}
function translateError(e){const map={FORBIDDEN:'Seu usuário não tem permissão para esta ação.',INVALID_REQUEST:'Adicione pelo menos um componente ou insumo.',INVALID_REQUEST_ITEMS:'Confira o produto, a quantidade e a unidade dos itens.',SELECT_EXACT_PRODUCTS:'Escolha cada componente ou insumo exatamente na lista do estoque.',SELECT_SUPPLIERS_FIRST:'Selecione pelo menos um fornecedor antes de iniciar a cotação.',REQUEST_ALREADY_QUOTED:'Esta cotação já recebeu respostas e não pode ter seus itens substituídos.',INVALID_CONTACT_EMAIL:'Confira os e-mails dos contatos de cotação.',INVALID_SUPPLIER_LOGO:'Escolha uma imagem JPG, PNG ou WebP com até 10 MB.',INVALID_QUOTE_RESPONSE:'A planilha não contém uma resposta válida.',INVALID_REQUEST_SUPPLIER:'O fornecedor não pertence a esta cotação.',INVALID_ORDER_DOCUMENT:'Selecione um arquivo válido com até 20 MB.',INVALID_TRACKING_STATUS:'Escolha um status válido para o acompanhamento.',FX_UNAVAILABLE:'Não foi possível consultar a cotação do Banco Central agora.',SELECT_OFFERS_FIRST:'Selecione uma oferta antes de emitir o pedido.',SELECT_ALL_OFFERS:'Selecione uma oferta para cada item.',INVALID_RECEIPT_QUANTITY:'A quantidade recebida é maior que o saldo do pedido.',INVALID_ORDER_ITEM:'Vincule o item a um produto do estoque antes de receber.'};return map[e]||e}
