async function reload(){D=await api('/bootstrap');$('loading').classList.add('hidden');$('app').classList.remove('hidden');render();if(startupProductId){const id=startupProductId,p=product(id);startupProductId='';const url=new URL(location.href);url.searchParams.delete('product_id');history.replaceState(null,'',url);openRequest();if(p){const row=document.querySelector('[data-item-row]');selectProductInRow(row,p)}}}
