function renderFx(){const x=D.fx;$('fxBadge').textContent=x?`Dólar BC venda: ${Number(x.rate).toLocaleString('pt-BR',{minimumFractionDigits:4,maximumFractionDigits:4})} · ${new Date(x.rate_at).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}`:'Dólar BC: atualizar';}
