  document.querySelectorAll('[data-issue]').forEach(b=>b.onclick=()=>openIssue(b.dataset.issue));
  document.querySelectorAll('[data-edit-request]').forEach(b=>b.onclick=()=>openRequest(b.dataset.editRequest));
  document.querySelectorAll('[data-export-request]').forEach(b=>b.onclick=()=>openQuoteDispatch(b.dataset.exportRequest));
