function itemHtml(it){
  const list=offers(it.item_id),selected=list.find(x=>x.selected),best=[...list].filter(x=>x.total_price!=null).sort((a,b)=>Number(a.total_price)-Number(b.total_price))[0],p=product(it.inventory_product_id);
  const conversion=best?.currency==='USD'&&best.exchange_rate_current&&best.total_price!=null?` · hoje ${money(Number(best.total_price)*Number(best.exchange_rate_current),'BRL')}`:'';
  return`<div class="item-row"><div><b>${esc(it.description)}</b><small class="muted">${p?`Estoque: ${esc(p.pn)} · saldo ${num(p.balance)} ${esc(p.unit||'')}`:'Produto não localizado no estoque'}</small></div><div><b>${num(it.quantity)}</b><small>${esc(it.unit)}</small></div><div class="offer">${selected?`Selecionado: <b>${esc(supplierName(selected.supplier_id,selected.supplier_name_snapshot))}</b>${D.permissions.values?' · '+money(selected.total_price,selected.currency):''}`:best?`${list.length} resposta(s) · menor ${D.permissions.values?money(best.total_price,best.currency)+conversion:'valor restrito'}`:'Nenhuma resposta importada'}</div><div class="card-actions">${D.permissions.approve&&list.length?`<button class="btn small primary" data-select-offer="${it.item_id}">Comparar respostas</button>`:''}</div></div>`}
