function renderSuppliers(){$('supplierList').innerHTML=D.suppliers.map(s=>{const contacts=supplierContacts(s.supplier_id);return`<article class="supplier"><h3>${esc(s.name)}</h3><div class="muted">${esc(s.document||'Documento não informado')}</div><div>${esc(s.phone||'')}</div><div class="contact-list">${contacts.map(x=>`<div>${esc(x.name||'Contato')} · ${esc(x.email)}</div>`).join('')||'Sem contato de cotação'}</div>${D.permissions.supplier?`<button class="btn small" data-contacts="${s.supplier_id}">Editar contatos</button>`:''}</article>`}).join('')||'<div class="empty">Nenhum fornecedor cadastrado.</div>';document.querySelectorAll('[data-contacts]').forEach(b=>b.onclick=()=>openContacts(b.dataset.contacts))}
