async function readResponseFile(expectedRequestId,file){
  if(!window.XLSX)throw Error('A biblioteca Excel ainda está carregando.');
  const wb=XLSX.read(await file.arrayBuffer(),{type:'array'}),quote=wb.Sheets['Cotação'],control=wb.Sheets['Controle'];if(!quote||!control)throw Error('Use a planilha gerada pelo Portal Livion.');
  const meta=XLSX.utils.sheet_to_json(control,{defval:''}),template=String(meta[0]?.template||''),rows=XLSX.utils.sheet_to_json(quote,{range:['LIVION_QUOTE_V2','LIVION_QUOTE_V3'].includes(template)?6:5,defval:''});
  if(!meta.length||!['LIVION_QUOTE_V1','LIVION_QUOTE_V2','LIVION_QUOTE_V3'].includes(template)||String(meta[0].request_id)!==expectedRequestId)throw Error('A planilha não pertence a esta cotação.');
  const supplierId=String(meta[0].supplier_id),supplier=D.suppliers.find(x=>x.supplier_id===supplierId);if(!supplier)throw Error('Fornecedor da planilha não encontrado.');
  const originals=new Map(requestItems(expectedRequestId).map(x=>[String(x.item_id),x]));
  const parsed=meta.map((m,i)=>{const row=rows[i]||{},itemId=String(m.request_item_id),original=originals.get(itemId),quantity=Number(original?.quantity||0),total=quoteNumberValue(row['Valor total']),legacyUnit=quoteNumberValue(row['Valor unitário']);if(template==='LIVION_QUOTE_V3'&&!(total>=0))throw Error(`Item ${i+1}: informe o valor total.`);return{item_id:itemId,description:String(original?.description||row['Descrição']||''),quantity,unit:String(original?.unit||row['Unidade']||''),currency:String(row['Moeda']||'BRL').toUpperCase(),unit_price:template==='LIVION_QUOTE_V3'?(quantity>0?total/quantity:null):legacyUnit,delivery_days:quoteDeliveryDays(row['Prazo de entrega (dias)'],i+1),payment_terms:quotePaymentTerms(row['Condição de pagamento'],i+1),delivery_method:row['Forma de entrega'],supplier_reference:row['Referência do fornecedor'],notes:row['Observações']}});
  openResponseReview(expectedRequestId,supplier,file,parsed);
}

async function createOutlookDraft(request,supplier,popup=null){
  popup?.close();
  const contactRows=supplierContacts(supplier.supplier_id),addresses=contactRows.flatMap(x=>String(x.email||'').split(/[;,]/)).map(x=>x.trim()).filter(Boolean);
  if(!addresses.length)throw Error('Cadastre ao menos um contato de cotação para este fornecedor.');
  const primary=contactRows.find(x=>x.is_primary)||contactRows[0],contactName=String(primary?.name||'').trim()||'responsável pela cotação',q=await quoteWorkbook(request,supplier),number=`COT-${String(request.request_number).padStart(6,'0')}`,subject=`Cotação Livion - ${supplier.name} - ${number}`;
  const html=`<html><body style="font-family:Segoe UI,Arial,sans-serif;font-size:11pt;color:#172033"><p>Olá, ${esc(contactName)}.</p><p>Gostaríamos de solicitar sua cotação para os itens detalhados na planilha anexa.</p><p>Por favor, preencha os campos destacados em amarelo, incluindo moeda, <b>valor total da quantidade solicitada</b>, prazo de entrega somente em dias, condição de pagamento no formato 30/60/90, forma de entrega, referência e observações. A aba “Como preencher” contém um exemplo.</p><p><b>Cotação:</b> ${number}<br><b>Data:</b> ${quoteDate(request.created_at||new Date())}</p><p>Pedimos a gentileza de devolver a planilha preenchida em resposta a este e-mail.</p><p>Atenciosamente,<br>${esc(D.user?.name||'Equipe Livion')}<br>Livion Solutions</p></body></html>`;
  const boundary=`livion_${crypto.randomUUID().replaceAll('-','')}`,eml=[`X-Unsent: 1`,`To: ${addresses.join('; ')}`,`Subject: ${mimeWord(subject)}`,'MIME-Version: 1.0',`Content-Type: multipart/mixed; boundary="${boundary}"`,'',`--${boundary}`,'Content-Type: text/html; charset="UTF-8"','Content-Transfer-Encoding: base64','',mimeLines(base64Bytes(new TextEncoder().encode(html))),`--${boundary}`,`Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet; name="${q.filename}"`,`Content-Disposition: attachment; filename="${q.filename}"`,'Content-Transfer-Encoding: base64','',mimeLines(base64Bytes(q.buffer)),`--${boundary}--`,''].join('\r\n'),emailFile=`${number}_${supplier.name.replace(/[^a-z0-9_-]+/gi,'_')}.eml`;
  downloadBlob(new Blob([eml],{type:'message/rfc822'}),emailFile);flash(`E-mail preparado para ${supplier.name}, com a planilha anexada.`);alert(`O e-mail foi preparado com o Excel anexado.\n\nAbra o arquivo ${emailFile} que acabou de ser baixado. Ele abrirá como uma nova mensagem no Outlook clássico instalado no Windows.`);
}
